cases.bad:
// onMouseMove: không có text dưới cursor → resetHover() (xoá lastHoveredTerm)
if (!defaultGetCaretRange(x, y)) { this.resetHover(); return; }
// Hệ quả: cursor đi qua khe giữa 2 từ → lookup lại từ cũ

cases.good:
// Giữ nguyên nhánh preserve state, chỉ thêm điều kiện surface vào guard:
if (!defaultGetCaretRange(x, y)) {
  if (this.lastHoveredTerm !== null) { this.cancelPendingHover(); return; }
  this.resetHover(); return;
}
// và guard same-occurrence chỉ chặn khi popup còn mở
